import os
import django

os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'VerifiHireAI_backend.settings')
django.setup()

from django.db import connection

queries = [
    """CREATE TABLE IF NOT EXISTS "api_securitysession" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "session_id" uuid NOT NULL UNIQUE, "token" varchar(128) NOT NULL, "user_id" varchar(128) NULL, "session_type" varchar(32) NOT NULL, "status" varchar(24) NOT NULL, "action" varchar(16) NOT NULL, "blocked_app" varchar(128) NULL, "blocked_process_name" varchar(255) NULL, "blocked_app_path" text NULL, "blocked_hardware" varchar(512) NULL, "reason" text NULL, "is_active" boolean NOT NULL, "last_heartbeat" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);""",
    """CREATE TABLE IF NOT EXISTS "api_identity_link" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "email" varchar(254) NOT NULL, "pan_number" varchar(10) NOT NULL, "pan_image" varchar(100) NULL, "snapshot_image" varchar(100) NULL, "face_features" jsonb NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);""",
    """CREATE INDEX IF NOT EXISTS "api_securitysession_session_id_4468f7f0" ON "api_securitysession" ("session_id");""",
    """CREATE INDEX IF NOT EXISTS "api_securitysession_token_d3cf2a2a" ON "api_securitysession" ("token");""",
    """CREATE INDEX IF NOT EXISTS "api_securitysession_token_d3cf2a2a_like" ON "api_securitysession" ("token" varchar_pattern_ops);""",
    """CREATE INDEX IF NOT EXISTS "api_securitysession_user_id_b113c495" ON "api_securitysession" ("user_id");""",
    """CREATE INDEX IF NOT EXISTS "api_securitysession_user_id_b113c495_like" ON "api_securitysession" ("user_id" varchar_pattern_ops);""",
    """CREATE INDEX IF NOT EXISTS "api_securit_token_e660f1_idx" ON "api_securitysession" ("token");""",
    """CREATE INDEX IF NOT EXISTS "api_securit_user_id_5c55f0_idx" ON "api_securitysession" ("user_id");""",
    """CREATE INDEX IF NOT EXISTS "api_securit_session_97693f_idx" ON "api_securitysession" ("session_type", "created_at");""",
    """ALTER TABLE "api_identity_link" ADD CONSTRAINT "api_identity_link_email_pan_number_0e41ca73_uniq" UNIQUE ("email", "pan_number");""",
    """CREATE INDEX IF NOT EXISTS "api_identit_email_a3de92_idx" ON "api_identity_link" ("email", "pan_number");"""
]

with connection.cursor() as cursor:
    for q in queries:
        try:
            cursor.execute(q)
        except Exception as e:
            print(f"Skipped/Error on {q[:30]}: {e}")

print("Tables created successfully.")
